GameEditorData.EnumTooltips.SmartActionType = {
    [0] = "No action type is specified. Do not use because it will cause errors on start-up.",
    [1] = "Creature says a creature_text line",
    [2] = "Set faction of target",
    [3] = "Morph the creature to a CreatureId (by taking its model) or a given ModelId. If both parameters are 0, demorph the creature",
    [4] = "Play a sound",
    [5] = "Play en emote",
    [6] = "Set a certain quest of our (player) target to 'fail', making them have to re-take it",
    [7] = "Add a quest to our (player) target's quest list",
    [8] = "ReactState. Can be Passive (0), Defensive (1), Aggressive (2).",
    [9] = "Activate a gameobject (targets our target_type, so it must be a gameobject)",
    [10] = "Play a random emote. Out of a total of 6 parameters it will pick one and ignore all fields with the value 0",
    [11] = "Cast a spell to our target type",
    [12] = "Summons a creature for a given time (or permanent, depending on the summon type which is set in the second parameter)",
    [13] = "Add or remove a certain percentage of threat from our current threat. Only one of the parameters (so either 1 or 2) may be used at the same time",
    [14] = "Add or remove a certain percentage of threat from our current threat. Only one of the parameters (so either 1 or 2) may be used at the same time",
    [15] = "Complete a quest requirement (by entry) of our current (player) target",
    [17] = "Set emote state",
    [20] = "Stop or Continue Automatic Attack.",
    [21] = "Allow or disallow moving while the creature is in combat",
    [22] = "Set the creature's event phase to a new value (warning: this is NOT the creature's actual phase!)",
    [23] = "Increment or decrement the creature's event phasemask (warning: this is NOT the creature's actual phase!)",
    [24] = "Makes the creature evade and therefore make it stop attacking and leave combat.",
    [25] = "Makes the creature flee for assistance of nearby friendly units",
    [26] = "Complete a quest requirement (by entry) of our current (player) target.",
    [27] = "Complete a quest requirement (by entry) of our current (player) target. Completes a killed monster credit as well as gives credit for a spellcast.",
    [28] = "Remove an aura/spell from our target",
    [29] = "Makes the creature follow the target at a certain distance and with a certain angle.",
    [30] = "Set the creature's event phase (note: this is NOT the creature's actual phase!)",
    [31] = "Set the creature's event phase randomly between two values (this is NOT the creature's actual phase!)",
    [32] = "Reset a gameobject, usually used to open/close a door (calls GameObject::ResetDoorOrButton)",
    [33] = "Gives a kill credit to our (player) target. The entry is the same entry as quest_template.RequiredNpcOrGo(1/2/3/4).",
    [34] = "Calls InstanceScript::SetData(field, data) or InstanceScript::SetBossState(field, EncounterState(data)) depending on type.",
    [35] = "Calls SetGuidData(field, guid) using the GUID from the first action target.",
    [36] = "Updates the creature's entry to a new one, making it become a completely different unit.",
    [37] = "Kills the target.",
    [38] = "Sets the creature in combat with its zone, can be used in instances and open world. Useful for creatures inside instances so all players will be set in combat until the fight ends. It only sets NPCs in combat with players, this only works with the target_type 9 - CREATURE_RANGE",
    [39] = "Makes the creature cry/call for help, which makes nearby creatures that are not yet in combat and are able to assist this creature, run to this creature and attack its attackers.",
    [40] = "Set the sheathe state of the creature. The sheath state determines which weapon will be displayed on the model.",
    [41] = "Despawns the creature/gameobject within a given time (in milliseconds).",
    [42] = "Sets the creature's invincibility health to a flat value or percentage. Either one of the parameters must be set (so not both). Setting both to 0 will remove the effect.",
    [43] = "Sets the mount model to the model given in the second parameter (or takes the model of the entry given in the first parameter). Only one parameter may be used at the same time.",
    [44] = "Sets the ACTUAL phasemask of the creature. This is not the event phasemask, but the actual phasemask. Sets the phasemask column in the creature table in the world database.",
    [45] = "Calls SMART_EVENT_DATA_SET with given field and data, making it possible to communicate between different entries.",
    [46] = "Stop melee, spell casting during combat, chasing the target and facing",
    [47] = "Sets the visibility of the creature or gameobject",
    [48] = "If a creature or GO is set active it will stay active even if no player is near. WARNING: keeping them active needs additional resources (CPU/RAM), the grid where the creature or object is located cannot be unloaded and other objects/creatures nearby also stay active",
    [49] = "Makes the creature start attacking the first unit it finds on the target list.",
    [50] = "Summon a gameobject entry. Use the Target to set the spawn position. If an entity is specified as target and also coordinates are set (target x,y,z), those coordinates are handled as offset from the target's position",
    [51] = "Kills the unit target instantly",
    [52] = "Activates a taxipath of the given id for our (player) target.",
    [53] = "Starts a waypoint path from the `waypoint_data` table.",
    [54] = "Pauses the waypoint path the creature is currently following for a specific time (milliseconds).",
    [55] = "Stops the waypoint path the creature is currently following. Also allows you to specify a despawn time from that point on as well as which quest id should be counted as 'fail' (or not, based on the third parameter).",
    [56] = "Adds item(s) to our player target.",
    [57] = "Removes item(s) from our player target.",
    [59] = "Sets running flag on or off.",
    [60] = "Disables or enables gravity, making the creature hover in place.",
    [62] = "Teleports the target to a specific map using coordinates in the target X/Y/Z/O fields. Note: May NOT use SMART_TARGET_POSITION (8)!",
    [63] = "Stores a decimal variable (number) under a variable id to store information for the creature during runtime. (The values set here can stack together compared to in Set Data).",
    [64] = "Stores a list of targets under a variable id so it can later be read again.",
    [65] = "Resumes the waypoint path the creature was previously following.",
    [66] = "Used to alter the source's orientation. Depends on the script target. If SMART_TARGET_SELF, facing will be the same as in HomePosition, For SMART_TARGET_POSITION you need to set target_o : 0 = North, West = 1.5, South = 3, East = 4.5",
    [67] = "Calls SMART_EVENT_UPDATE after a specific time with given parameters.",
    [68] = "Plays a movie of a given entry.",
    [69] = "PointId is called by SMART_EVENT_MOVEMENTINFORM. Continue this action with the TARGET_TYPE column. Use any target_type, and use target_x, target_y, target_z as the coordinates, if an entity is specified as target and also coordinates are set (target x,y,z) those coordinates are handled as offset from the target's position",
    [70] = "Makes a temporarily disabled gameobject usable again for the given duration.",
    [71] = "Set the creature's equipment template to a certain entry. If no entry (first parameter) is set, it will set the three item entries which are ordered by slot (param3 is main-hand, param4 is off-hand, param5 is gun/bow/etc). The slotmask (param2) value is 0 by default and goes by bits, so if it's '2' it will only show the off-hand weapon (bits are 1, 2 and 4). Having 0 defaults to 7, so all slots.",
    [72] = "Closes the currently opened gossip to our player target.",
    [73] = "Calls SMART_EVENT_TIMED_EVENT_TRIGGERED with a given id.",
    [74] = "Interrupts the timed event called from SMART_ACTION_TRIGGER_TIMED_EVENT. 0 is NOT a proper value!",
    [78] = "Calls SMART_EVENT_RESET (only calls this, doesn't actually reset the creature/gameobject).",
    [79] = "Sets the creature's attack distance and angle to chase its target with. The distance (first parameter) is the minimum distance it will keep away from its target during combat.",
    [80] = "Calls a script for the source with a given entry.",
    [81] = "Set the npc flags of the target (using creature_template.npcflag)",
    [82] = "Adds npc flags of the target (using creature_template.npcflag)",
    [83] = "Removes npc flags of the target (using creature_template.npcflag)",
    [84] = "Makes a player say text (just like SMART_ACTION_TALK, except that it makes the player target say it). Does NOT trigger SMART_EVENT_TEXT_OVER.",
    [85] = "Make the target cast spell on it self",
    [86] = "Make the specified target type (in parameters) cast a spell to our target type",
    [87] = "Calls a random script for the source with given entries",
    [88] = "Calls a random script between two values for the source with given entries. So if parameter 1 is 500 and parameter 2 is 550, a script will randomly be picked between 500 and 550.",
    [89] = "Creature moves to A random position in given radius. (Only works when it is not in combat)",
    [90] = "Set the unit field bytes 1 flags of the target to a specific value",
    [91] = "Removes specific unit field bytes 1 flags of the target",
    [92] = "This action allows you to interrupt the current spell being cast. If you do not set the spellId, the base-abstract-classes will find the current spell depending on the withDelay and the withInstant values.",
    [97] = "Jump to a given position with a given speed. Must use SMART_TARGET_SELF with this action_type. If selfJump is 1 the actor will jump to the target (you can add an offset from the target's position by also specifying target coordinates), if selfJump is 0 the targeted creature will jump to the target XYZO position. A speed value around 12 is normal speed",
    [98] = "Sends a specific gossip menu to a player which will then be opened for this player",
    [99] = "Sets the gameobject's loot state to a given value",
    [100] = "Sends a stored target id to our given target type. The id comes from SMART_ACTION_STORE_TARGET and can be used with SMART_TARGET_STORED",
    [101] = "Sets the home position of the source to a new position. The home position is the position the creature runs to when evading/resetting/etc. Uses the target type to determine the new home position.",
    [102] = "Turns the health regeneration of the creature on or off",
    [103] = "Roots or unroots the creature (or player target).",
    [107] = "Summon a set of creatures in once using the creature_summon_groups table of the world database. Target has no effect here.",
    [108] = "Sets the value of a given power type to a specific value",
    [109] = "Adds a given value to a given power type",
    [110] = "Removes a given value from a given power type",
    [111] = "Stops a game event with specified id (game_event.eventEntry)",
    [112] = "Starts a game event with specified id (game_event.eventEntry)",
    [113] = "Creature starts Waypoint Movement using the closest path id in the range of pathId1 and pathId2. Use waypoints table to create movement.",
    [114] = "Moves the creature to an offset relative to its own facing. The offset is taken from the target x/y/z fields, not from the action params.",
    [115] = "Play a random sound",
    [116] = "Allows setting the delay of corpse decay time.",
    [117] = "Allows toggling if target can evade or not.",
